sys_script_include.script:
var CreateTasksFromSystemProperty = Class.create();
CreateTasksFromSystemProperty.prototype = {
    initialize: function() {
        // Load the system properties
        this.bulkProperty = gs.getProperty('custombulk.property');
        this.walkProperty = gs.getProperty('customwalk.properties');
        this.runProperty = gs.getProperty('customrun.properties'); // Corrected variable name

        // Parse the properties into JSON objects
        this.bulkData = this.bulkProperty ? JSON.parse(this.bulkProperty) : {};
        this.walkData = this.walkProperty ? JSON.parse(this.walkProperty) : {};
        this.runData = this.runProperty ? JSON.parse(this.runProperty) : {}; // Fixed variable reference
    },

    createTasks: function() {
        // Create tasks from custombulk.property
        this.createTasksFromData(this.bulkData, 'custombulk.property');

        // Create tasks from customwalk.properties
        this.createTasksFromData(this.walkData, 'customwalk.properties');

        // Create tasks from customrun.properties
        this.createTasksFromData(this.runData, 'customrun.properties');
    },

    createTasksFromData: function(propertyData, propertyName) {
        for (var key in propertyData) {
            if (propertyData.hasOwnProperty(key)) {
                var data = propertyData[key];

                // Check if a task with the same short description already exists
                var existingTask = new GlideRecord('samp_sp_vb_task');
                existingTask.addQuery('short_description', data.short_description);
                existingTask.query();

                if (existingTask.next()) {
                    gs.info('Task with short description "' + data.short_description + '" already exists from ' + propertyName);
                } else {
                    // Create a new task record
                    var taskGR = new GlideRecord('samp_sp_vb_task');
                    taskGR.initialize();
                    taskGR.short_description = data.short_description;
                    taskGR.description = data.description;
                    taskGR.instruction = data.instruction;
                    taskGR.insert();  // Insert the task record
                    gs.info('Task created with short description: ' + data.short_description + ' from ' + propertyName);
                }
            }
        }
    },

    type: 'CreateTasksFromSystemProperty'
};
